program.compute:
pool = read('/input/options')
result = None
for count in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    result = read('/output/selection')
    if valid(result):
        if status('report') == 'not_sent':
            send('report', 'team', result)
        elif status('report') == 'sent':
            pass
        else:
            receipt_value = receipt('report')
            if receipt_value == 'success':
                pass
            elif receipt_value == 'unknown':
                status_value = status('report')
            else:
                send('report', 'team', result)
else:
    write('/output/selection', result)
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

